// Tidies the form fields, validates the email and builds the key used by the duplicate guard.
const form = $('Lead form submitted').item.json;
const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();

const email = clean(form.email).toLowerCase().replace(/^mailto:/, '');
const emailValid = email.length <= 254 && /^[a-z0-9._%+-]+@[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(email);
const [localPart, domain] = emailValid ? email.split('@') : ['', ''];

// Match key: ignore +tags everywhere and dots for Gmail, so one inbox is one lead.
const isGmail = domain === 'gmail.com' || domain === 'googlemail.com';
let keyLocal = localPart.split('+')[0];
if (isGmail) keyLocal = keyLocal.replace(/\./g, '');
const emailKey = emailValid ? `${keyLocal}@${isGmail ? 'gmail.com' : domain}` : '';

return {
  json: {
    submittedAt: form.submittedAt ?? new Date().toISOString(),
    name: clean(form.name),
    email,
    emailKey,
    emailDomain: domain,
    emailValid,
    company: clean(form.company),
    budget: clean(form.budget),
    message: clean(form.message),
  },
};

// Input: the rows the lookup found (an empty item when it found none).
// Output: every valid lead from this run, marked as duplicate or not.
const existingKeys = new Set(
  $input.all()
    .map((row) => String(row.json.emailKey ?? '').trim().toLowerCase())
    .filter(Boolean),
);
const seenInThisRun = new Set();

return $('Keep valid emails').all().map((lead) => {
  const key = lead.json.emailKey;
  const isDuplicate = existingKeys.has(key) || seenInThisRun.has(key);
  seenInThisRun.add(key);
  return { json: { ...lead.json, isDuplicate } };
});

// Simple, explainable scoring. Edit the points to suit your business.
const config = $('Set sheet and scoring rules').first().json;
const { emailValid, isDuplicate, ...lead } = $json;

// Keys must match the Budget options in the form.
const BUDGET_POINTS = {
  'Over 5,000': 35,
  '1,000 to 5,000': 25,
  'Under 1,000': 10,
  'Not sure yet': 5,
};

let score = 0;
const reasons = [];
const add = (points, reason) => {
  if (!points) return;
  score += points;
  reasons.push(`+${points} ${reason}`);
};

const freeDomains = (config.freeEmailDomains ?? []).map((d) => String(d).toLowerCase());
add(freeDomains.includes(lead.emailDomain) ? 0 : 30, 'business email address');
add(lead.company ? 10 : 0, 'company named');
add(BUDGET_POINTS[lead.budget] ?? 0, `budget: ${lead.budget}`);
add(lead.message.length >= 80 ? 15 : lead.message.length >= 20 ? 5 : 0, 'message describes the need');

let tier = 'cold';
if (score >= config.hotScore) tier = 'hot';
else if (score >= config.warmScore) tier = 'warm';

return { json: { ...lead, score, tier, scoreReasons: reasons.join(', ') } };

